from h import *
A = dict(id="A", levels=L1, kind="Recipe web page", source="Everyday Kitchen website", title="Easy shakshuka", body=[
 {"p": "Shakshuka is a tasty breakfast dish from Israel. It is made with eggs cooked in a spicy tomato sauce."},
 {"p": "You will need: **4 eggs**, **1 onion**, **2 red peppers**, **1 tin of tomatoes** and **1 teaspoon of cumin**."},
 {"p": "Cook the chopped onion and peppers for ten minutes. Add the tomatoes and cumin, then cook for five more minutes. Next, crack the eggs into the sauce and cook until they are firm. Serve with fresh bread. It takes about thirty minutes to make, and it serves four people."}])
B = dict(id="B", levels=L1, kind="Magazine article", source="Table & Trail food magazine", title="Eating your way around the markets of Israel", body=[
 {"p": "If you want to understand a country, visit its food markets. In Israel, the biggest markets, such as the Carmel Market in Tel Aviv and the Mahane Yehuda Market in Jerusalem, are noisy, colourful places where stallholders shout out their prices and the smell of fresh bread fills the air. Markets are also where local people do their everyday shopping, not just tourists. Allow at least two hours to explore."},
 {"h": "What can you eat?"},
 {"p": "Almost every market has a stall selling falafel, which are crispy balls made from chickpeas, usually served in warm pitta bread with salad. You will also find hummus, a smooth dip made from chickpeas, tahini (a paste made from sesame seeds) and lemon. Many cafés serve small dishes called \"mezze\", which are shared by everyone at the table. Fresh pitta is baked in the market every hour, so it is often still warm when you buy it."},
 {"h": "More than food"},
 {"p": "Look out for the spice stalls, which sell bags of colourful spices piled high in sacks. There are also stalls selling fresh fruit and vegetables, olives, cheese, dried fruit and nuts. Many vendors are happy to let customers taste before they buy. Some markets also have musicians, so you can enjoy a tune while you shop."},
 {"h": "When should you go?"},
 {"p": "Friday is the busiest day. Many shops close for Shabbat, the day of rest, which begins on Friday evening, so people shop for the weekend before it starts. Food writer Yael Cohen advises going in the morning: \"The crowds are smaller and the fruit and vegetables are at their freshest.\""},
 {"p": "Whatever time you go, bring cash and wear comfortable shoes. The falafel at the Carmel Market is the best in the world, and you will fall in love with the food."}])
C = dict(id="C", levels=L1, kind="Online review", source="Taste Tours review page", title="Review: Tel Aviv market food tour", body=[
 {"p": "Rating: 4 out of 5 stars"},
 {"p": "We booked this three-hour food tour on our second day in Tel Aviv, and it was a delicious way to see the city. Our guide, Dani, was friendly and funny, and he knew everyone at the market."},
 {"p": "The best part was the tasting stops. We tried warm falafel, creamy hummus and sweet, sticky pastries, and every single dish was fantastic. Dani also took us to a spice stall, where we learned how to tell fresh spices from old ones. He also told us the story behind each dish, and he gave us a map so we could find our favourite stalls again the next day. The tour started on time and finished exactly when promised."},
 {"p": "However, the tour was too crowded. There were 25 people in our group, so it was hard to hear Dani over the noise of the market. It was also very hot, and we only stopped for water once."},
 {"p": "Top tips:"},
 {"ul": ["Come hungry, because there is a lot to eat.", "Wear a hat and bring a bottle of water.", "Book the morning tour to avoid the crowds."]},
 {"p": "I would definitely recommend this tour, but only if the group were smaller!"}])

